import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import * as schema from './schema';

export type Db = ReturnType<typeof createDb>;

/** Folder of SQL migrations generated by drizzle-kit (`pnpm db:generate`). */
export const MIGRATIONS_FOLDER = resolve(process.cwd(), 'drizzle');

/** Opens (creating if needed) a SQLite database and brings it up to the latest migration. */
export function createDb(path: string) {
	if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
	const sqlite = new Database(path);
	sqlite.pragma('journal_mode = WAL');
	sqlite.pragma('foreign_keys = ON');
	const db = drizzle(sqlite, { schema });
	migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
	return db;
}

/** A transaction handle; anything that only reads and writes rows accepts either. */
export type Tx = Parameters<Parameters<Db['transaction']>[0]>[0];
export type Conn = Db | Tx;
